export const uid=()=>crypto.randomUUID();
export function dayKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
export function offsetDate(days,base=dayKey()){const d=new Date(base+'T12:00:00');d.setDate(d.getDate()+days);return dayKey(d)}
export function daysBetween(a,b){return Math.round((new Date(b+'T12:00:00Z')-new Date(a+'T12:00:00Z'))/86400000)}
const milestone=(id,title,days)=>({id,title,date:offsetDate(days),done:false});
