export function publicPlan(plan){const dated=plan.milestones.filter(m=>m.date);const canCount=Boolean(plan.start&&dated.length);return {id:plan.id,name:plan.name,category:plan.category,intro:plan.intro,image:plan.image,coverSrc:plan.coverSrc||null,publicValues:plan.publicValues||[],videos:plan.videos||[],programDays:plan.programDays||[],programTags:plan.programTags||[],horizon:plan.horizon,duration:canCount?Math.max(1,...dated.map(m=>daysBetween(plan.start,m.date))):null,milestones:plan.milestones.map(m=>({title:m.title,day:plan.start&&m.date?Math.max(1,daysBetween(plan.start,m.date)):null})),habits:plan.habits.map(h=>({full:h.full,light:h.light}))}}
export function copyTemplate(template,start=dayKey()){return {id:uid(),name:template.name,category:template.category,start,horizon:template.horizon,why:'',values:'',vision:'',intro:template.intro,visibility:'private',image:template.image,coverSrc:template.coverSrc||null,videos:structuredClone(template.videos||[]),programDays:structuredClone(template.programDays||[]),programTags:structuredClone(template.programTags||[]),milestones:template.milestones.map(m=>({id:uid(),title:m.title,date:offsetDate(m.day,start),done:false})),habits:template.habits.map(h=>({id:uid(),full:h.full,light:h.light,reminder:''}))}}
export function validMilestones(rows,start=''){if(!rows.length)throw Error('Add at least one milestone.');for(const m of rows){if(!m.title.trim())throw Error('Give every milestone a name.');if(m.date&&(!/^\d{4}-\d{2}-\d{2}$/.test(m.date)||!Number.isFinite(new Date(m.date+'T12:00:00').getTime())))throw Error('Choose a valid target date or leave it blank.');if(start&&m.date&&m.date<start)throw Error('Milestone dates must be on or after the plan start date.')}return rows.slice().sort((a,b)=>a.date&&b.date?a.date.localeCompare(b.date):a.date?-1:b.date?1:(a.flexOrder??0)-(b.flexOrder??0))}
