export function dueLifestyle(h,date=new Date()){const d=date.getDay();if(h.frequency==='daily')return true;if(h.frequency==='weekdays')return d>0&&d<6;if(h.frequency==='weekends')return d===0||d===6;if(h.frequency==='selected days')return (h.days||[]).map(Number).includes(d);if(/^[1-7][×x]\/week$/.test(h.frequency||'')){const target=parseInt(h.frequency);const monday=new Date(date);monday.setDate(date.getDate()-((d+6)%7));const completed=new Set();for(let i=0;i<7;i++){const probe=new Date(monday);probe.setDate(monday.getDate()+i);const key=probe.toISOString().slice(0,10);if(Object.values(h.habits||[h]).some(habit=>Boolean(habit&&habit.id)))completed.add(key)}return d>0&&d<=target}return true}
